import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
export function grove(host){const frame=new THREE.Group();frame.name='BLDC Driver open burgundy HY2.0-4P';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.65}),metal=materials.metal(0xb9ad82,{roughness:.44}),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'BLDC Driver Grove '+n);for(const x of[-4.65,4.65]){box([.7,5.2,6.5],[x,0,-3.25],'side wall');box([.85,.75,3.1],[Math.sign(x)*3.85,2.2,-4.8],'guide rail');box([.7,.9,.6],[x,2.05,0],'mouth ear');}box([8.6,.7,6.5],[0,-2.25,-3.25],'floor');box([8.6,5.2,.6],[0,0,-6.2],'rear wall');box([8.6,2.65,3.6],[0,-1.25,-4.7],'contact carrier');box([3.4,.65,2.7],[0,1.2,-5.1],'locking tongue');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4],[(i-1.5)*2,-.15,-3.2],`contact ${i+1}`,metal));box([.42,1.2,.42],[(i-1.5)*2,-1.4,-5.7],`PCB tail ${i+1}`,metal);}const port=host.add(new Port({id:'grove',label:'PORT.A · I2C',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.15],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',protocol:'I2C',i2cAddress:'0x65',scope:'Physical four contacts,cable pose and documentary labels only;no bus,GPIO,PWM,electrical,motor,firmware or protection logic'}}));return{frame,contacts,port};}
export function terminal(host){const frame=new THREE.Group();frame.name='BLDC Driver fixed orange HT3.96-4P motor socket';frame.position.fromArray(spec.terminal.position);host.body.add(frame);const orange=materials.plastic(0xf59d52,{roughness:.64}),metal=materials.metal(0xb7b8a6,{roughness:.45}),parts=[],box=(s,p,n,m=orange)=>{const q=mesh(frame,new THREE.BoxGeometry(...s),m,p,'BLDC Driver fixed terminal '+n);parts.push(q);return q;};const rear=box([16,.7,3.5],[0,-9.65,0],'rear support');for(const sign of[-1,1])box([.65,9.3,3.5],[sign*7.675,-4.65,0],'side cheek');box([14.7,9.3,.24],[0,-4.65,-1.63],'lower retention floor');box([14.7,6.95,.3],[0,-3.475,1.6],'upper forward wall');box([14.7,.85,.3],[0,-8.875,1.6],'upper rear wall');for(const x of[-7.5,-3.96,0,3.96,7.5])box([.55,1.5,.3],[x,-7.7,1.6],'real slot partition');box([16,.5,.3],[0,-8.45,1.6],'slot rear rib');const contacts=[],tails=[];for(const x of spec.terminal.pinX){contacts.push(box([.62,7.2,.62],[x,-4.6,-.5],'recessed phase contact',metal));tails.push(box([.62,.62,5.0],[x,-8.65,-3],'concealed PCB pin tail',metal));}const port=host.add(new Port({id:'terminal',label:'U / V / W / COM · HT3.96-4P',connector:'ht3.96-4p',position:spec.terminal.position,hitSize:[16,1,3.5],pins:spec.terminal.names.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:3.96,center:[0,-.5],order:col=>col+1},meta:{role:'visual-connector',face:'top',pinOrderEvidence:'Exact-model front label left-to-right U,V,W,COM.Slot index is physical front-view order;schematic J2 pins4,3,2,1 respectively.',scope:'Physical four-pole motor socket,plug attachment and documentary labels only;no winding,motor,rotor,PWM,commutation,load,current,electrical,protection or firmware behavior'}}));return{frame,rear,parts,contacts,tails,port};}
